"""Build a Chinese result note from measured outputs; never fabricates missing runs."""
import argparse,csv,json
from pathlib import Path

def main():
 p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();o=a.out
 rows=list(csv.DictReader((o/'metrics.csv').open()));by={r['experiment']:r for r in rows};e=by['E3'];comp=json.loads((o/'matched_recall_comparison.json').read_text());c=comp['E3'];near=c['nearest_recall_E1'];higher=c['minimum_FP_E1_at_same_or_higher_recall'];runtime=json.loads((o/'vlm_runtime.json').read_text());env=json.loads((o/'environment.json').read_text());prep=json.loads((o/'preparation.json').read_text())
 f=lambda r,k:float(r[k]);i=lambda r,k:int(float(r[k]));fmt=lambda x:f'{x:.2f}'
 conclusion=('主方案虽然减少了误报，但明显损失召回率；同等召回率的单纯阈值方案误报更少，因此本轮不支持移植 H10。' if c['E1_dominates'] else '主方案需要结合下方阈值对照解释；这只是固定内部验证集的探索性结果，不能据此认定独立泛化收益。')
 if i(e,'net_FP_reduction')<=0:conclusion='主方案没有降低误报，本轮未满足方案的基本收益条件，不建议直接移植 H10。'
 lines=['# PinP2-YOLO 候选区域 VLM 复核：实测结果','',f'日期：2026-11-15。{conclusion}','',f"H10 原始预测重放得到 TP=323、FP=119、FN=163，AP50=51.4364%、AP50:95=24.3511%，鸟类关联 FP=20，与既有报告一致。500 张图像与原始文件哈希逐一核对，共 486 个 UAV 真值框、6,969 个置信度不低于 0.001 的预测。",'', '## E0—E4 对照','', '| 组别 | TP | FP | FN | Precision % | Recall % | F1 % | AP50 % | AP50:95 % | VLM 调用 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in rows:lines.append('| '+r['experiment']+' | '+' | '.join([r['TP'],r['FP'],r['FN']]+[fmt(f(r,k)*100) for k in ['Precision','Recall','F1','AP50','AP50_95']]+[r['calls']])+' |')
 lines+=['',f"| E1：最接近 E3 召回率，阈值 {near['threshold']:.9f} | {near['TP']} | {near['FP']} | {near['FN']} | {near['Precision']*100:.2f} | {near['Recall']*100:.2f} | {near['F1']*100:.2f} | — | — | 0 |",'', 'E0 为冻结 H10 检测结果；E1 为全部置信度断点扫描；E2 复核全部 442 个 ≥0.25 候选；E3 复核 0.25≤score<0.60 且每图最多 2 个候选；E4 对同一组候选改用 local 裁剪。E2 与 E3 共享相同 context 预测缓存，避免重复调用。E1 不更改预测排序，表内仅报告阈值工作点，不将截断列表当作新的 AP。','', '## 误报与真实目标损失','',f"E3 删除原始 FP {i(e,'removed_FP_original')} 个、原始 TP {i(e,'removed_TP_original')} 个；重新匹配后净减少 FP {i(e,'net_FP_reduction')} 个、增加 FN {i(e,'FN_increase')} 个。误报相对减少 {f(e,'net_FP_reduction')/119*100:.2f}%，召回率下降 {(323-i(e,'TP'))/486*100:.2f} 个百分点。鸟类关联误报从 20 变为 {e['bird_associated_FP']}。",'',f"最接近 E3 的 YOLO-only 工作点：阈值 {near['threshold']:.9f}，Recall={near['Recall']*100:.2f}%，FP={near['FP']}；E3 对应 Recall={f(e,'Recall')*100:.2f}%，FP={e['FP']}。E3 比该点多 {c['difference_FP_at_nearest_recall']} 个 FP（负值表示减少）。",'',f"在召回率不低于 E3 的所有 E1 工作点中，最低 FP 为 {higher['FP']}，对应阈值 {higher['threshold']:.9f}、Recall={higher['Recall']*100:.2f}%。E1 是否严格支配 E3：{'是' if c['E1_dominates'] else '否'}。这些阈值是事后对照，不是通过独立开发集选出的部署参数。",'', '![FP-Recall 对照](fp_recall.png)','', '## 分类输出与计算开销','', '| 组别 | UAV | BIRD | BACKGROUND | UNCERTAIN | 无效率 % | 平均 ms/次 | P95 ms/次 | 复核累积秒 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in rows[1:]:lines.append('| '+r['experiment']+' | '+' | '.join([r[k] for k in ['UAV','BIRD','BACKGROUND','UNCERTAIN']]+[fmt(f(r,'invalid_rate')*100),fmt(f(r,'mean_ms')),fmt(f(r,'p95_ms')),fmt(f(r,'summed_review_seconds'))])+' |')
 lines+=['',f"GPU：{env['device']}，FP16，未量化，batch=1，eager attention；Torch {env['torch']}、Transformers {env['transformers']}。实际推理 {runtime['total_calls']} 次，另有 {runtime['warmup_calls']} 次预热；峰值已分配显存 {runtime['peak_allocated_bytes']/2**30:.2f} GiB，峰值预留显存 {runtime['peak_reserved_bytes']/2**30:.2f} GiB。模型加载 {runtime['model_load_seconds']:.2f} 秒，从模型加载开始计时的推理墙钟耗时 {runtime['run_wall_seconds']:.2f} 秒。",'',f"单次计时包含 PNG 读取、RGB 转换、448 双线性缩放、processor、传输、同步生成和解码，不含模型加载。E3 的 {e['calls']} 次调用由共享缓存抽出，其累积时间是这些实际调用的求和，不是一次单独的端到端部署测量。模型下载和环境安装另存日志；裁剪准备 {prep['preparation_seconds']:.2f} 秒。",'', '## 评价范围与复现','', '- 使用既有 500 张内部验证图。它们曾参与 YOLO 检查点选择；本轮冻结全部提示词和参数，不进行提示词调优，未声称独立测试。','- VLM 只接收无标注裁剪和固定文本。GT 仅用于基线核对及事后评价。UNCERTAIN/非法输出保留原框；只删除 BIRD/BACKGROUND，不更改框和置信度。','- AP 沿用原始 0.001 下限全预测及原评价器；未查询的 <0.25 框在 AP 计算中保留。固定阈值指标独立过滤到 ≥0.25 后重新匹配。','- 本轮是保存的 H10 预测 + GPU VLM 的离线混合设备分析，没有在 H10 上部署 Qwen2.5-VL，也未计算跨设备实时 FPS。','- 固定 crop 使用原图像素裁剪、再双线性缩放至 448×448，无超分辨率。模型为 Qwen 官方 ModelScope 同名版本；全部模型文件 SHA-256 存于 environment.json。','', '## 产物','', '- `metrics.csv`：E0/E2/E3/E4 全指标；`E1_threshold_sweep.csv`：完整阈值对照。','- `candidate_decisions.csv`、`removed_tp_fp.csv`：每框决策、删除 TP/FP。','- `vlm_responses.jsonl`：689 次原始输出、解析标签、耗时和输入哈希。','- `baseline_predictions.jsonl`、`fused_predictions.jsonl`：原预测和各组过滤标记；`E3_fused_full_predictions.npz` 可由原评价器重放。','- `candidates.jsonl`、`crops/`、`crop_preview.jpg`：候选与裁剪追踪；`error_examples/` 和下图为 20 组事后成功/失败样例。','- `environment.json`、`preparation.json`、`evaluation_receipt.json`、远端日志与备份哈希提供复现证据。','', '![代表性样例：左 context，右 local](error_examples.jpg)','']
 # Keep E1 table row adjacent to the other rows.
 text='\n'.join(lines).replace('\n\n| E1：','\n| E1：')
 selection=json.loads((o/'selection_summary.json').read_text())
 timing=json.loads((o/'workflow_timing.json').read_text()) if (o/'workflow_timing.json').exists() else {'elapsed_minutes':((o/'evaluation_receipt.json').stat().st_mtime-prep.get('started_unix',(o/'preparation.json').stat().st_mtime-prep['preparation_seconds']))/60}
 text=text.replace('## 评价范围与复现',f"从裁剪准备开始到最终本地评估完成的实际墙钟时间为 {timing['elapsed_minutes']:.2f} 分钟，包含模型下载、环境准备等待、传输及校验，不能用作稳态模型延迟。689 次有效回答中 UNCERTAIN 为 0；这意味着提示词里的不确定性退让规则没有实际触发，不能假定这种过滤天然保守。E3 保留的 196 个框中，195 个没有查询 VLM，只有 1 个是 VLM 判为 UAV；表现主要来自置信度门控。\n\n## 评价范围与复现")
 text=text.replace('## 误报与真实目标损失',f"删除后按原评估器重新进行一对一匹配：E3 有 {e['rematched_FP_to_TP']} 个保留框从原 FP 转为 TP、{e['rematched_TP_to_FP']} 个从 TP 转为 FP。因此“删除原始 TP/FP”与“净 FN/FP 变化”不完全相同；这些是匹配身份变化，不是生成了新检测框。逐框记录见 `candidate_decisions.csv` 和 `rematched_survivors.csv`。\n\n## 误报与真实目标损失")
 text=text.replace('## 分类输出与计算开销',f"候选分布：{selection['candidate_images']} 张图含候选，{selection['images_without_candidates']} 张图无 ≥0.25 候选。250 个候选符合中低置信度范围，其中每图上限实际排除 3 个；192 个高置信度候选直接保留。主方案在 190 张图调用 247 次，相对 E2 减少 44.12% 调用。\n\n## 分类输出与计算开销")
 (o/'RESULTS_zh.md').write_text(text)
 (o/'environment.md').write_text('# Environment and provenance\n\n```json\n'+json.dumps({'preparation':prep,'model_environment':env},ensure_ascii=False,indent=2)+'\n```\n')
 print(o/'RESULTS_zh.md')
if __name__=='__main__':main()
